-- Amorçage de la taxonomie v2 (chantier 1 : refonte des archétypes).
--
-- Jusqu'ici la taxonomie n'entrait en base que par `prisma/seed-archetypes.ts`,
-- lancé à la main. La production a donc gardé l'ancien catalogue pendant que les
-- environnements locaux avaient le nouveau. On en fait une migration : elle
-- s'applique une fois par environnement, au déploiement, sans intervention.
--
-- Même contrat que le seed : `upsert` par id, `published` n'est jamais touché
-- sur une ligne existante (la migration `retire_purged_archetypes` reste
-- maîtresse de ce champ, et les retraits faits depuis l'admin sont préservés).
INSERT INTO "quest_archetypes" (
  "id", "title", "description", "title_en", "description_en", "category",
  "target_traits", "comfort_level", "requires_outdoor", "requires_social",
  "minimum_duration_minutes", "fallback_quest_id", "quest_pace"
) VALUES
  (1, 'Le Voyage Aléatoire', 'Aller à la gare sans destination. Prendre un billet pour la ville dont le nom te dit le moins quelque chose. Passer l''après-midi sur place sans chercher les lieux touristiques, puis rentrer en ayant noté trois choses que tu n''aurais jamais vues autrement.', 'The Random Journey', 'Go to the station with no destination. Buy a ticket to the town whose name means the least to you. Spend the afternoon there without looking up the sights, then head home having noted three things you would never have seen otherwise.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.92,"thrillSeeking":0.9,"emotionalStability":0.7,"boredomSusceptibility":0.7}'::jsonb, 'extreme'::"QuestComfortLevel", true, false, 240, 242, 'planned'::"QuestArchetypePace"),
  (25, 'L''Arrêt Inconnu', 'Prendre une ligne de bus que tu n''empruntes jamais, descendre à un arrêt au hasard et marcher 20 minutes sans itinéraire fixé.', 'The Unknown Stop', 'Take a bus line you never use, get off at a random stop, and walk 20 minutes with no fixed route.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.85,"thrillSeeking":0.7,"emotionalStability":0.65}'::jsonb, 'high'::"QuestComfortLevel", true, false, 120, 63, 'instant'::"QuestArchetypePace"),
  (37, 'La Rose des Vents', 'Tracer une direction au hasard sur une carte (ou une appli) et marcher au moins 15 minutes dans cette direction sans but précis.', 'The Wind Rose', 'Pick a random direction on a map (or app) and walk at least 15 minutes that way with no fixed goal.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.8,"thrillSeeking":0.6,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 240, 'instant'::"QuestArchetypePace"),
  (50, 'Le Fil de l''Eau', 'Marcher au moins 30 minutes le long d''un cours d''eau, d''un canal ou d''une voie verte sans objectif précis.', 'The Waterline', 'Walk at least 30 minutes along a river, canal, or greenway with no fixed goal.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.75,"thrillSeeking":0.45,"emotionalStability":0.62}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 90, 79, 'instant'::"QuestArchetypePace"),
  (63, 'Le Terminus Vierge', 'Prendre un bus ou un tram jusqu''à un terminus que tu n''as jamais visité et marcher 20 minutes sur place.', 'The Virgin Terminus', 'Take a bus or tram to a terminus you''ve never visited, then walk 20 minutes there.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.82,"thrillSeeking":0.65,"boredomSusceptibility":0.55,"emotionalStability":0.62}'::jsonb, 'high'::"QuestComfortLevel", true, false, 120, 25, 'instant'::"QuestArchetypePace"),
  (73, 'Le Circuit Mémoire', 'Planifier et parcourir à pied ou en transports trois lieux qui ont compté dans ton passé (ancienne école, premier appart, lieu d''un souvenir fort) en une demi-journée, seul·e, sans téléphone en main.', 'The Memory Circuit', 'Plan and visit on foot or public transit three places that mattered in your past (old school, first flat, place of a strong memory) in half a day, alone, without phone in hand.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.6,"emotionalStability":0.55,"thrillSeeking":0.35}'::jsonb, 'high'::"QuestComfortLevel", true, false, 180, 25, 'planned'::"QuestArchetypePace"),
  (79, 'Le Trajet du Troisième Bus', 'Aller à un arrêt de bus près de chez toi. Laisser passer deux bus, quels qu''ils soient. Monter dans le troisième. Descendre à un arrêt choisi d''avance par un chiffre aléatoire (par exemple le 5ᵉ après le tien). Explorer 30 minutes autour à pied, puis revenir.', 'The Third Bus', 'Go to a bus stop near home. Let two buses pass, whichever they are. Board the third one. Get off at a stop chosen beforehand by a random number (say, the 5th after yours). Explore on foot for 30 minutes around, then come back.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.82,"thrillSeeking":0.72,"boredomSusceptibility":0.65}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 90, 37, 'instant'::"QuestArchetypePace"),
  (237, 'La Ville d’à Côté', 'Aller dans une ville que tu n''as jamais visitée à moins d''une heure de chez toi, sans rien préparer, et y passer l''après-midi entier.', 'The Town Next Door', 'Go to a town you have never visited less than an hour from home, with nothing planned, and spend the whole afternoon there.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.9,"thrillSeeking":0.72,"emotionalStability":0.7}'::jsonb, 'high'::"QuestComfortLevel", true, false, 240, 25, 'planned'::"QuestArchetypePace"),
  (238, 'La Carte Rendue', 'Sortir de chez toi et marcher deux heures sans téléphone et sans carte, jusqu''à ne plus savoir où tu es. Rentrer en demandant ton chemin à des passants.', 'The Map Given Up', 'Leave home and walk two hours with no phone and no map, until you no longer know where you are. Find your way back by asking passersby.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.95,"thrillSeeking":0.8,"emotionalStability":0.78}'::jsonb, 'extreme'::"QuestComfortLevel", true, false, 180, 73, 'planned'::"QuestArchetypePace"),
  (239, 'Le Quartier Étranger', 'Passer deux heures à pied dans le quartier de ta ville où tu ne vas jamais, en entrant dans au moins trois lieux où tu n''es jamais entré.', 'The Foreign District', 'Spend two hours on foot in the neighborhood of your city you never go to, entering at least three places you have never set foot in.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.8,"thrillSeeking":0.62,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 120, 50, 'instant'::"QuestArchetypePace"),
  (240, 'La Nuit du Quartier', 'Refaire à deux heures du matin un trajet que tu ne fais qu''en plein jour. Marcher lentement et regarder ce qui change.', 'The Neighborhood at Night', 'Walk at two in the morning a route you only ever take in daylight. Go slowly and look at what changes.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.8,"thrillSeeking":0.62,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 37, 'instant'::"QuestArchetypePace"),
  (241, 'Les Trois Points Hauts', 'Trouver trois points de vue en hauteur de ta ville dans la même journée et les rejoindre à pied, l''un après l''autre.', 'The Three High Points', 'Find three elevated viewpoints in your city in one day and reach them all on foot, one after the other.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.8,"thrillSeeking":0.62,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 90, 50, 'planned'::"QuestArchetypePace"),
  (242, 'Le Train Sans Retour Prévu', 'Aller à la gare, prendre le premier train qui part, descendre au troisième arrêt, et trouver seul comment rentrer.', 'The Train With No Return Booked', 'Go to the station, take the first train leaving, get off at the third stop, and work out how to get home on your own.', 'spatial_adventure'::"QuestPsychologicalCategory", '{"openness":0.95,"thrillSeeking":0.8,"emotionalStability":0.78}'::jsonb, 'extreme'::"QuestComfortLevel", true, false, 240, 1, 'planned'::"QuestArchetypePace"),
  (2, 'Le Dîner Solitaire', 'Réserver une table pour une personne dans un restaurant où tu n''irais jamais seul, et t''y tenir. Téléphone éteint au fond de la poche, pas de livre, pas de carnet. Commander une entrée, un plat, un dessert, et rester jusqu''au café.', 'The Solo Dinner', 'Book a table for one at a restaurant you would never go to alone, and keep the booking. Phone off, deep in your pocket, no book, no notebook. Order a starter, a main and a dessert, and stay through coffee.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.82,"extraversion":0.3,"openness":0.6}'::jsonb, 'high'::"QuestComfortLevel", true, false, 90, 223, 'instant'::"QuestArchetypePace"),
  (26, 'Le Banc Silencieux', 'Rester assis seul sur un banc public 30 minutes : pas d''écran, pas de casque, seulement présence.', 'The Silent Bench', 'Sit alone on a public bench for 30 minutes: no screen, no headphones—just presence.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.72,"extraversion":0.35,"boredomSusceptibility":0.3}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 30, 228, 'instant'::"QuestArchetypePace"),
  (38, 'Le Café Sans Écran', 'Passer 30 minutes dans un café avec un carnet ou un livre papier, téléphone éteint ou mode avion.', 'The Screen-Free Café', 'Spend 30 minutes in a café with a notebook or paper book—phone off or in airplane mode.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.68,"extraversion":0.4,"conscientiousness":0.55}'::jsonb, 'low'::"QuestComfortLevel", true, false, 30, 51, 'instant'::"QuestArchetypePace"),
  (51, 'Le Dernier Rang', 'T''asseoir au dernier rang d''un lieu public ouvert (sport, pratique culturelle) 25 minutes : observer, pas d''écran.', 'The Back Row', 'Sit in the back row of an open public venue (sport, cultural practice) for 25 minutes—observe, no screen.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.72,"extraversion":0.38,"openness":0.55}'::jsonb, 'low'::"QuestComfortLevel", true, false, 25, 98, 'instant'::"QuestArchetypePace"),
  (98, 'Le Solo au Comptoir', 'Commander un truc au comptoir d''un café ou d''un snack et rester debout là pour le consommer, sans écran.', 'The Counter Solo', 'Order something at a café or snack counter and stand right there to consume it, no screen.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.6,"extraversion":0.4,"conscientiousness":0.5}'::jsonb, 'low'::"QuestComfortLevel", true, false, 20, 9, 'instant'::"QuestArchetypePace"),
  (222, 'L’Heure Immobile', 'Rester assis une heure pleine dans un lieu public passant, sans rien faire : pas d''écran, pas de livre, pas de carnet. Soutenir l''ennui et les regards.', 'The Motionless Hour', 'Sit for one full hour in a busy public place doing nothing: no screen, no book, no notebook. Hold the boredom and the looks.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.84,"extraversion":0.42,"openness":0.7}'::jsonb, 'high'::"QuestComfortLevel", true, false, 60, 26, 'instant'::"QuestArchetypePace"),
  (223, 'Le Repas Seul en Terrasse', 'Déjeuner seul en terrasse d''un lieu fréquenté, en pleine heure de pointe, sans écran ni lecture. Regarder les gens au lieu de t''occuper.', 'Lunch Alone Outside', 'Eat lunch alone on a busy terrace at peak hour, with no screen and nothing to read. Watch people instead of keeping busy.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.84,"extraversion":0.42,"openness":0.7}'::jsonb, 'high'::"QuestComfortLevel", true, false, 90, 2, 'instant'::"QuestArchetypePace"),
  (224, 'Le Banc des Retrouvailles', 'T''asseoir dans une gare ou un aéroport sans avoir de train ni d''avion à prendre, et observer les arrivées pendant 45 minutes.', 'The Arrivals Bench', 'Sit in a station or an airport with no train or plane to catch, and watch the arrivals for 45 minutes.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.74,"extraversion":0.32,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 45, 26, 'planned'::"QuestArchetypePace"),
  (225, 'Le Cinéma Solitaire', 'Aller seul au cinéma un soir, sans prévenir personne avant ni après, et rester assis jusqu''à la toute fin du générique.', 'The Solo Cinema', 'Go to the cinema alone one evening, telling nobody before or after, and stay seated until the very end of the credits.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.74,"extraversion":0.32,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 120, 38, 'planned'::"QuestArchetypePace"),
  (226, 'Le Concert Sans Personne', 'Assister seul à un concert, un match ou un spectacle où tout le monde vient en groupe. Rester jusqu''au bout.', 'The Concert Alone', 'Go alone to a concert, a match or a show where everyone else comes in groups. Stay until the end.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.84,"extraversion":0.42,"openness":0.7}'::jsonb, 'high'::"QuestComfortLevel", true, false, 180, 225, 'planned'::"QuestArchetypePace"),
  (227, 'La Terrasse Sans But', 'Commander une boisson dans un café et rester une heure entière sans rien faire d''autre que regarder la rue.', 'The Aimless Terrace', 'Order a drink at a café and stay a full hour doing nothing but watching the street.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.74,"extraversion":0.32,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 38, 'instant'::"QuestArchetypePace"),
  (228, 'L’Attente Volontaire', 'Dans une file d''attente, laisser passer trois personnes devant toi et attendre ton tour sans rien faire d''autre. Sans téléphone.', 'The Chosen Wait', 'In a queue, let three people go ahead of you and wait your turn doing nothing else. No phone.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.74,"extraversion":0.32,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 30, 26, 'instant'::"QuestArchetypePace"),
  (229, 'Le Musée d’Une Seule Salle', 'Aller dans un musée et ne regarder qu''une seule œuvre, pendant une heure entière. Ne pas visiter le reste.', 'The One-Room Museum', 'Go to a museum and look at one single work for a full hour. Do not visit the rest.', 'public_introspection'::"QuestPsychologicalCategory", '{"emotionalStability":0.74,"extraversion":0.32,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 90, 227, 'planned'::"QuestArchetypePace"),
  (3, 'La Nuit Étoilée', 'Sortir de la ville jusqu''à un endroit où l''on voit vraiment les étoiles, et y rester de la nuit tombée jusqu''à ce que le froid te renvoie. Pas de musique, pas d''écran, aucune photo. Au retour, écrire la seule pensée qui est revenue le plus souvent.', 'The Starry Night', 'Get out of the city to somewhere the stars are genuinely visible, and stay from nightfall until the cold sends you back. No music, no screen, no photos. On returning, write down the one thought that kept coming back.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.55,"conscientiousness":0.55,"boredomSusceptibility":0.3,"emotionalStability":0.6}'::jsonb, 'extreme'::"QuestComfortLevel", true, false, 240, 215, 'planned'::"QuestArchetypePace"),
  (18, 'L''Œil Nu', 'Prendre trente photos en une heure, sans filtre, sans retouche et sans en supprimer une seule. Le soir, garder la seule qui te semble vraie et effacer les vingt-neuf autres.', 'The Naked Eye', 'Take thirty photos in an hour, no filter, no editing, deleting none of them. That evening, keep the one that feels true and delete the other twenty-nine.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.7,"conscientiousness":0.55,"boredomSusceptibility":0.4}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 217, 'instant'::"QuestArchetypePace"),
  (27, 'La Marche Sans Musique', 'Une promenade d''au moins 20 minutes en silence total, sans musique ni podcast.', 'The Walk Without Music', 'Walk at least 20 minutes in total silence—no music or podcast.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.5,"conscientiousness":0.55,"boredomSusceptibility":0.35}'::jsonb, 'low'::"QuestComfortLevel", true, false, 30, 9, 'instant'::"QuestArchetypePace"),
  (76, 'Le Dîner Aveugle', 'Préparer un vrai repas (deux plats) puis te bander les yeux ou éteindre toute lumière pour le manger entièrement à l''aveugle. Pas de musique, pas de téléphone. Goûter chaque bouchée comme si tu ignorais ce qu''elle contient.', 'The Blind Dinner', 'Cook a real meal (two dishes) then blindfold yourself or switch off all lights to eat it entirely in the dark. No music, no phone. Taste each bite as if you didn''t know what it contained.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.75,"conscientiousness":0.62,"emotionalStability":0.65,"boredomSusceptibility":0.3}'::jsonb, 'high'::"QuestComfortLevel", false, false, 60, 217, 'planned'::"QuestArchetypePace"),
  (214, 'Les Trois Heures Sans Son', 'Trois heures sans aucun son produit volontairement : pas de musique, pas de podcast, pas de vidéo, pas une parole. Écrire ensuite ce qui est remonté pendant.', 'Three Hours Without Sound', 'Three hours with no sound you chose to make: no music, no podcast, no video, not a word spoken. Afterward, write what surfaced.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.8,"conscientiousness":0.68,"boredomSusceptibility":0.42}'::jsonb, 'high'::"QuestComfortLevel", false, false, 180, 27, 'planned'::"QuestArchetypePace"),
  (215, 'La Marche Aveugle', 'Te faire guider les yeux bandés par une personne de confiance pendant une heure, dehors. Ne jamais soulever le bandeau, même une seconde.', 'The Blind Walk', 'Have someone you trust guide you blindfolded for an hour, outdoors. Never lift the blindfold, not for a second.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.88,"conscientiousness":0.76,"boredomSusceptibility":0.5}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 60, 76, 'planned'::"QuestArchetypePace"),
  (216, 'La Chambre Noire', 'Passer deux heures dans le noir complet : pas d''écran, pas de lumière, pas de sommeil. Rester éveillé et assis.', 'The Dark Room', 'Spend two hours in complete darkness: no screen, no light, no sleeping. Stay awake and seated.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.8,"conscientiousness":0.68,"boredomSusceptibility":0.42}'::jsonb, 'high'::"QuestComfortLevel", false, false, 120, 76, 'planned'::"QuestArchetypePace"),
  (217, 'Le Repas d’un Seul Goût', 'Manger un repas entier composé d''un seul aliment, lentement, sans rien pour l''accompagner et sans rien pour te distraire.', 'The Single-Flavor Meal', 'Eat an entire meal made of one single food, slowly, with nothing alongside it and nothing to distract you.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.7,"conscientiousness":0.58,"boredomSusceptibility":0.32}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 60, 18, 'instant'::"QuestArchetypePace"),
  (218, 'Le Froid Tenu', 'Terminer ta douche par trois minutes d''eau franchement froide. Ne pas réduire, ne pas écourter. Respirer lentement au lieu de fuir.', 'The Cold Held', 'End your shower with three minutes of genuinely cold water. Do not turn it down, do not cut it short. Breathe slowly instead of fleeing.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.8,"conscientiousness":0.68,"boredomSusceptibility":0.42}'::jsonb, 'high'::"QuestComfortLevel", false, false, 30, 27, 'instant'::"QuestArchetypePace"),
  (219, 'La Journée Sans Musique', 'Une journée entière sans aucune musique ni fond sonore, y compris dans les transports et en cuisinant. Noter le moment où le silence a été le plus dur.', 'The Day Without Music', 'A full day with no music and no background audio, including on your commute and while cooking. Note the moment silence was hardest.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.7,"conscientiousness":0.58,"boredomSusceptibility":0.32}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 240, 27, 'planned'::"QuestArchetypePace"),
  (220, 'Le Toucher Seul', 'Identifier vingt objets de chez toi les yeux fermés, uniquement au toucher. Noter les cinq que tu n''as pas reconnus.', 'Touch Alone', 'Identify twenty objects in your home with your eyes closed, by touch only. Write down the five you failed to recognize.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.7,"conscientiousness":0.58,"boredomSusceptibility":0.32}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 45, 27, 'instant'::"QuestArchetypePace"),
  (221, 'La Nuit Sans Réveil', 'Dormir une nuit sans alarme, sans téléphone dans la chambre, et te lever quand ton corps le décide. Noter l''heure au réveil.', 'The Night Without an Alarm', 'Sleep one night with no alarm and no phone in the room, and get up when your body decides. Note the time when you wake.', 'sensory_deprivation'::"QuestPsychologicalCategory", '{"openness":0.7,"conscientiousness":0.58,"boredomSusceptibility":0.32}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 240, 219, 'planned'::"QuestArchetypePace"),
  (4, 'L''Explorateur Local', 'Choisir sur une carte un village de moins de mille habitants à moins d''une heure de chez toi. T''y rendre sans rien préparer, entrer dans le seul commerce ouvert, et faire parler la personne derrière le comptoir jusqu''à repartir avec une histoire du lieu.', 'The Local Explorer', 'Pick a village of under a thousand people within an hour of home. Go with nothing planned, walk into the one shop that is open, and get the person behind the counter talking until you leave with a story about the place.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.72,"agreeableness":0.6,"openness":0.78,"thrillSeeking":0.6}'::jsonb, 'high'::"QuestComfortLevel", true, true, 240, 75, 'planned'::"QuestArchetypePace"),
  (28, 'Le Lieu du Commerçant', 'Demander à un commerçant local son endroit préféré dans le coin et s''y rendre une fois.', 'The Merchant''s Pick', 'Ask a local shopkeeper their favorite spot nearby and go there once.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.6,"agreeableness":0.65,"openness":0.68}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 120, 255, 'planned'::"QuestArchetypePace"),
  (40, 'Le Voisin du Quartier', 'Demander à un voisin ou un commerçant ce qu''il changerait en premier dans le quartier — et noter une idée retenue.', 'The Neighborhood Neighbor', 'Ask a neighbor or shopkeeper what they would change first in the area—and note one idea you keep.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.55,"agreeableness":0.72,"openness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 45, 67, 'planned'::"QuestArchetypePace"),
  (53, 'L''Accueil Visiteur', 'Participer à une réunion d''accueil, un apéro nouveaux arrivants ou un club avec tour de présentation.', 'The Visitor Welcome', 'Join a welcome meetup, newcomers drink, or club with introductions.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.8,"agreeableness":0.65,"openness":0.68,"thrillSeeking":0.45}'::jsonb, 'high'::"QuestComfortLevel", false, true, 90, 253, 'planned'::"QuestArchetypePace"),
  (66, 'Le Salut Cordial', 'Sur un trajet quotidien, saluer volontairement trois inconnus (voisin, commerçant, passant) avec un regard franc et une phrase simple.', 'The Cordial Hello', 'On a daily commute, deliberately greet three strangers (neighbor, shopkeeper, passer-by) with a direct look and one simple sentence.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.55,"agreeableness":0.65,"openness":0.5}'::jsonb, 'low'::"QuestComfortLevel", true, true, 20, 112, 'instant'::"QuestArchetypePace"),
  (67, 'Le Message Rendormi', 'Reprendre contact avec une personne que tu n''as pas contactée depuis plus de six mois, par un message court et honnête, sans attendre de réponse immédiate.', 'The Sleeping Message', 'Reach out to someone you haven''t contacted in more than six months, with a short honest message, without expecting an immediate reply.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.45,"agreeableness":0.7,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 114, 'instant'::"QuestArchetypePace"),
  (75, 'Le Troc Sauvage', 'Prendre un objet de chez toi que tu ne regretteras pas (livre, vêtement, ustensile) et te rendre dans un marché, un vide-grenier ou un quartier marchand pour proposer un troc — pas un paiement — à trois vendeurs. Rentrer avec quelque chose que tu n''aurais jamais acheté.', 'The Wild Barter', 'Take an item from home you won''t miss (a book, a piece of clothing, a utensil) and head to a market, flea market or shopping street to propose a barter — not a payment — to three vendors. Come back with something you would never have bought.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"openness":0.78,"extraversion":0.65,"thrillSeeking":0.6,"agreeableness":0.5}'::jsonb, 'high'::"QuestComfortLevel", true, true, 120, 66, 'planned'::"QuestArchetypePace"),
  (112, 'La Question au Commerçant', 'À ta prochaine course, demander au commerçant son conseil sur un produit — et suivre sa réponse.', 'The Shopkeeper''s Advice', 'On your next errand, ask the shopkeeper for advice on a product — and follow it.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.5,"agreeableness":0.6,"openness":0.55}'::jsonb, 'low'::"QuestComfortLevel", true, true, 15, 9, 'instant'::"QuestArchetypePace"),
  (114, 'Le Voisin d''Ascenseur', 'Dans le prochain ascenseur, métro ou file, engager une phrase anodine avec un·e inconnu·e (« beau temps », « long trajet aussi ? »).', 'The Elevator Neighbor', 'On your next elevator, metro or queue, start a casual sentence with a stranger (''nice weather'', ''long trip too?'').', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.55,"agreeableness":0.55,"thrillSeeking":0.35}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 15, 115, 'instant'::"QuestArchetypePace"),
  (115, 'Le Nom Retenu', 'La prochaine personne qui se présente à toi, tu retiens son prénom ET tu le réutilises au moins deux fois dans la conversation.', 'The Remembered Name', 'The next person who introduces themselves, remember their name AND use it at least twice during the conversation.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.5,"agreeableness":0.6,"conscientiousness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 15, 114, 'instant'::"QuestArchetypePace"),
  (252, 'Le Repas Chez l’Inconnu', 'Trouver un dîner participatif, une table d''hôtes ou un repas de quartier où tu ne connais absolument personne, et y aller seul.', 'Dinner Among Strangers', 'Find a supper club, a communal table or a neighborhood meal where you know absolutely nobody, and go alone.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.86,"agreeableness":0.82,"openness":0.88}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 240, 53, 'planned'::"QuestArchetypePace"),
  (253, 'Les Cinq Mêmes Questions', 'Aborder cinq inconnus dans la même journée et poser à chacun exactement la même question personnelle. Noter les cinq réponses mot pour mot.', 'The Same Five Questions', 'Approach five strangers in one day and ask each of them exactly the same personal question. Write down all five answers word for word.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.78,"agreeableness":0.74,"openness":0.8}'::jsonb, 'high'::"QuestComfortLevel", true, true, 90, 53, 'instant'::"QuestArchetypePace"),
  (254, 'Le Club Poussé', 'Te rendre à la première séance d''un club, d''un cours ou d''un collectif dont l''activité t''intimide. Y rester jusqu''à la fin.', 'The Door Pushed Open', 'Turn up to the first session of a club, class or group whose activity intimidates you. Stay until the end.', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.78,"agreeableness":0.74,"openness":0.8}'::jsonb, 'high'::"QuestComfortLevel", true, true, 120, 53, 'planned'::"QuestArchetypePace"),
  (255, 'L’Invitation Lancée', 'Inviter chez toi quelqu''un que tu apprécies mais que tu n''as jamais invité. Proposer une date précise, pas un « faudrait qu''on se voie ».', 'The Invitation Made', 'Invite to your home someone you like but have never invited. Propose a specific date, not a vague "we should meet up".', 'exploratory_sociability'::"QuestPsychologicalCategory", '{"extraversion":0.68,"agreeableness":0.64,"openness":0.7}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 60, 40, 'instant'::"QuestArchetypePace"),
  (5, 'Le Point Culminant', 'Monter à pied jusqu''au point le plus haut accessible de ta ville. Une fois en haut, rester trente minutes sans téléphone et répondre par écrit à une seule question : est-ce que je vais dans la direction que j''aurais choisie ?', 'The High Point', 'Walk up to the highest accessible point in your city. Once there, stay thirty minutes without your phone and answer one question in writing: am I going in the direction I would have chosen?', 'physical_existential'::"QuestPsychologicalCategory", '{"openness":0.65,"conscientiousness":0.55,"thrillSeeking":0.4}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 120, 29, 'instant'::"QuestArchetypePace"),
  (23, 'La Chose Repoussée', 'Nommer par écrit une chose précise qui te fait légèrement peur et que tu repousses depuis au moins un mois. La faire dans l''heure qui suit, même mal, même à moitié.', 'The Thing Put Off', 'Write down one precise thing that mildly scares you and that you have been putting off for at least a month. Do it within the hour, even badly, even halfway.', 'physical_existential'::"QuestPsychologicalCategory", '{"thrillSeeking":0.7,"openness":0.75,"emotionalStability":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 30, 235, 'instant'::"QuestArchetypePace"),
  (29, 'Le Trajet Lent', 'Refaire un trajet habituel à pied ou à vélo au lieu des transports ; noter une pensée à mi-parcours.', 'The Slow Commute', 'Redo a usual commute on foot or by bike instead of transit; note one thought halfway.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.58,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 90, 23, 'instant'::"QuestArchetypePace"),
  (54, 'Le Réveil Corps', 'Avant tout écran le matin, au moins 12 minutes d''étirements ou de mobilité douce en silence.', 'The Body Wake-Up', 'Before any screen in the morning, at least 12 minutes of stretches or gentle mobility in silence.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.72,"openness":0.48}'::jsonb, 'low'::"QuestComfortLevel", false, false, 20, 9, 'instant'::"QuestArchetypePace"),
  (74, 'L''Endurance du Plancher', 'Séance corps au sol de 45 minutes (gainage, respiration, mobilité lente) jusqu''à sortir de la zone de confort physique, chez toi, sans musique ni écran.', 'The Floor Endurance', 'A 45-minute floor session (core work, breathing, slow mobility) pushing through physical discomfort, at home, without music or screen.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.75,"emotionalStability":0.55,"thrillSeeking":0.5}'::jsonb, 'high'::"QuestComfortLevel", false, false, 45, 23, 'instant'::"QuestArchetypePace"),
  (77, 'Le Repas des Cinq Couleurs', 'Composer un repas qui contient cinq couleurs naturelles distinctes (blanc et noir ne comptent pas). Chercher, acheter, cuisiner — puis photographier le résultat avant la première bouchée et le manger lentement.', 'The Five-Color Meal', 'Assemble a meal with five distinct natural colors (white and black do not count). Shop, prep, cook — then photograph the result before the first bite and eat it slowly.', 'physical_existential'::"QuestPsychologicalCategory", '{"openness":0.68,"conscientiousness":0.58,"agreeableness":0.5}'::jsonb, 'low'::"QuestComfortLevel", false, false, 45, 54, 'instant'::"QuestArchetypePace"),
  (230, 'La Distance Jamais Faite', 'Marcher ou courir d''un trait la plus longue distance de ta vie, même modeste. S''arrêter quand le corps le dit vraiment, pas quand la tête le propose.', 'The Distance Never Covered', 'Walk or run, in one go, the longest distance of your life, however modest. Stop when your body actually says so, not when your head suggests it.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"emotionalStability":0.68,"thrillSeeking":0.55}'::jsonb, 'high'::"QuestComfortLevel", true, false, 180, 29, 'planned'::"QuestArchetypePace"),
  (231, 'Le Retour à Pied', 'Rentrer chez toi entièrement à pied depuis un endroit d''où tu prends toujours les transports, quelle que soit l''heure et quelle que soit la météo.', 'The Walk Home', 'Walk all the way home from a place you always take transit from, whatever the hour and whatever the weather.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"emotionalStability":0.68,"thrillSeeking":0.55}'::jsonb, 'high'::"QuestComfortLevel", true, false, 120, 29, 'instant'::"QuestArchetypePace"),
  (232, 'Le Sommet Local', 'Atteindre à pied le point le plus haut accessible autour de chez toi, et y rester trente minutes avant de redescendre.', 'The Local Summit', 'Reach on foot the highest accessible point near where you live, and stay there thirty minutes before coming back down.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"emotionalStability":0.68,"thrillSeeking":0.55}'::jsonb, 'high'::"QuestComfortLevel", true, false, 240, 5, 'planned'::"QuestArchetypePace"),
  (233, 'La Nuit Blanche Debout', 'Rester éveillé toute une nuit sans écran, avec un seul projet tenu du soir au lever du jour : écrire, marcher, ou penser.', 'The Night Kept Awake', 'Stay awake all night with no screen, holding one single project from dusk to daybreak: write, walk, or think.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.76,"thrillSeeking":0.63}'::jsonb, 'extreme'::"QuestComfortLevel", false, false, 240, 230, 'planned'::"QuestArchetypePace"),
  (234, 'Le Mauvais Temps Assumé', 'Sortir dehors par mauvais temps, sans capuche ni parapluie, et marcher trente minutes. Rentrer trempé et le noter.', 'Into the Bad Weather', 'Go outside in bad weather with no hood and no umbrella, and walk for thirty minutes. Come home soaked, and note it.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"emotionalStability":0.68,"thrillSeeking":0.55}'::jsonb, 'high'::"QuestComfortLevel", true, false, 60, 74, 'instant'::"QuestArchetypePace"),
  (235, 'Le Corps Regardé', 'Te tenir cinq minutes devant un miroir en pied, sans te détourner, et nommer à voix haute trois choses de ton corps que tu acceptes vraiment.', 'The Body Looked At', 'Stand five minutes in front of a full-length mirror without looking away, and say out loud three things about your body you genuinely accept.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.68,"emotionalStability":0.58,"thrillSeeking":0.45}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 30, 23, 'instant'::"QuestArchetypePace"),
  (236, 'L’Effort Jusqu’au Bout', 'Choisir un effort physique et le pousser jusqu''au point où tu voudrais arrêter, puis continuer deux minutes de plus. Exactement deux.', 'The Effort Past the Point', 'Pick a physical effort and push it to the point where you want to stop, then keep going two more minutes. Exactly two.', 'physical_existential'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"emotionalStability":0.68,"thrillSeeking":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, false, 90, 74, 'instant'::"QuestArchetypePace"),
  (6, 'L''Entraînement de l''Aube', 'Programmer une séance de sport seul, un matin de week-end, à une heure où personne ne se lève. Y aller sans musique, et ne l''annoncer à personne ni avant ni après.', 'The Dawn Workout', 'Schedule a solo workout for a weekend morning, at an hour when nobody is up. Go without music, and tell nobody before or after.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.88,"extraversion":0.3,"boredomSusceptibility":0.3}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 196, 'instant'::"QuestArchetypePace"),
  (86, 'La Règle des Trois Non', 'Durant une journée, refuser explicitement trois demandes ou sollicitations (pro, sociales, familiales) que tu aurais normalement acceptées par réflexe. Dire « non » sans t''excuser, sans argumenter longuement. Noter tes réactions intérieures et celles des autres.', 'The Rule of Three Nos', 'Over one day, explicitly refuse three requests (work, social, family) you would normally say yes to by reflex. Say ''no'' without apologizing, without long arguments. Write down your inner reactions and the others''.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.72,"emotionalStability":0.62,"agreeableness":0.35,"boredomSusceptibility":0.25}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 30, 188, 'instant'::"QuestArchetypePace"),
  (187, 'Le Contrat d''une Semaine', 'Écrire sur papier un engagement précis et daté pour les sept prochains jours. Le signer. Le confier à quelqu''un en lui donnant explicitement le droit de te le rappeler. Une seule chose, pas trois.', 'The One-Week Contract', 'Write down one precise, dated commitment for the next seven days. Sign it. Hand it to someone and explicitly give them the right to hold you to it. One thing, not three.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.65,"boredomSusceptibility":0.38}'::jsonb, 'high'::"QuestComfortLevel", false, false, 60, 196, 'planned'::"QuestArchetypePace"),
  (188, 'Le Réveil Sans Snooze', 'Demain matin, sortir du lit à la première sonnerie. Poser les deux pieds au sol avant toute autre pensée. Le soir, écrire une phrase sur ce que ça a changé au reste de la journée.', 'No Snooze', 'Tomorrow morning, get out of bed on the first alarm. Both feet on the floor before any other thought. That evening, write one line on what it changed about the rest of your day.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.55,"boredomSusceptibility":0.28}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 30, 197, 'instant'::"QuestArchetypePace"),
  (189, 'La Promesse Publique', 'Annoncer à trois personnes distinctes une chose que tu vas faire cette semaine, avec la date exacte. À partir de maintenant, ne rien annoncer que tu ne feras pas.', 'The Public Promise', 'Tell three separate people one thing you will do this week, with the exact date. From now on, announce nothing you will not do.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.65,"boredomSusceptibility":0.38}'::jsonb, 'high'::"QuestComfortLevel", false, true, 45, 196, 'planned'::"QuestArchetypePace"),
  (190, 'Le Projet Rouvert', 'Reprendre pendant deux heures pleines un projet que tu as abandonné il y a plus de six mois. L''objectif n''est pas de le finir : c''est de le rouvrir et de tenir les deux heures sans t''échapper.', 'The Reopened Project', 'Spend two full hours on a project you abandoned more than six months ago. The goal is not to finish it: it is to reopen it and hold the two hours without escaping.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.65,"boredomSusceptibility":0.38}'::jsonb, 'high'::"QuestComfortLevel", false, false, 120, 187, 'planned'::"QuestArchetypePace"),
  (191, 'La Journée Sans Retard', 'Arriver en avance à chacun de tes rendez-vous d''aujourd''hui, sans exception. Observer ce que ça coûte en organisation, et ce que ça change dans le regard des autres.', 'The Day Without Lateness', 'Arrive early to every single appointment today, no exceptions. Notice what it costs you to organize, and what it changes in how others look at you.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.55,"boredomSusceptibility":0.28}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 240, 188, 'planned'::"QuestArchetypePace"),
  (192, 'Le Chantier de Trois Heures', 'Choisir la tâche que tu repousses depuis le plus longtemps et y consacrer trois heures d''affilée, téléphone dans une autre pièce. Ne pas viser la fin, viser les trois heures.', 'The Three-Hour Push', 'Pick the task you have been putting off the longest and give it three unbroken hours, phone in another room. Do not aim to finish, aim for the three hours.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.65,"boredomSusceptibility":0.38}'::jsonb, 'high'::"QuestComfortLevel", false, false, 180, 190, 'planned'::"QuestArchetypePace"),
  (193, 'La Dette Réglée', 'Identifier une dette non financière : un service dû, une réponse jamais donnée, une promesse oubliée. La solder entièrement aujourd''hui, et dire à la personne que tu sais que tu étais en retard.', 'The Debt Settled', 'Identify one non-financial debt: a favor owed, an answer never given, a forgotten promise. Settle it in full today, and tell the person you know you were late.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.65,"boredomSusceptibility":0.38}'::jsonb, 'high'::"QuestComfortLevel", false, true, 60, 189, 'planned'::"QuestArchetypePace"),
  (194, 'Le Seuil Tenu', 'Fixer maintenant ton heure de coucher de ce soir et la respecter à cinq minutes près, quoi qu''il arrive. Noter ce que tu as dû interrompre pour y arriver.', 'The Line Held', 'Set your bedtime for tonight right now and hold it to within five minutes, whatever happens. Write down what you had to cut short to get there.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.55,"boredomSusceptibility":0.28}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 90, 188, 'instant'::"QuestArchetypePace"),
  (195, 'La Reprise du Lendemain', 'Refaire demain, exactement à la même heure, l''activité difficile que tu as faite aujourd''hui. Sans la nouveauté pour te porter, sans témoin, sans raison de le faire à part l''avoir décidé.', 'The Second Run', 'Tomorrow, at exactly the same hour, repeat the hard thing you did today. No novelty to carry you, no witness, no reason beyond having decided it.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.95,"emotionalStability":0.73,"boredomSusceptibility":0.46}'::jsonb, 'extreme'::"QuestComfortLevel", false, false, 240, 190, 'planned'::"QuestArchetypePace"),
  (196, 'Le Refus Écrit', 'Lister par écrit cinq choses auxquelles tu dis oui par habitude plutôt que par envie. En choisir une et la supprimer définitivement de ta vie cette semaine.', 'The Written Refusal', 'List five things you say yes to out of habit rather than desire. Pick one and remove it from your life for good this week.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.55,"boredomSusceptibility":0.28}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 45, 197, 'instant'::"QuestArchetypePace"),
  (197, 'L’Engagement du Matin', 'Au réveil, décider d''une seule chose à accomplir avant midi. L''écrire. Ne rien entreprendre d''autre tant qu''elle n''est pas faite.', 'The Morning Commitment', 'On waking, decide on one single thing to finish before noon. Write it down. Start nothing else until it is done.', 'async_discipline'::"QuestPsychologicalCategory", '{"conscientiousness":0.86,"emotionalStability":0.55,"boredomSusceptibility":0.28}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 30, 86, 'instant'::"QuestArchetypePace"),
  (7, 'La Détox Digitale', 'Supprimer les réseaux sociaux de ton téléphone pour vingt-quatre heures — les supprimer, pas les mettre en veille. Le lendemain, noter combien de fois ta main a cherché l''app absente, et ce que tu as fait à la place.', 'The Digital Detox', 'Delete social apps from your phone for twenty-four hours: delete them, do not just mute them. The next day, note how many times your hand reached for the missing app, and what you did instead.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.82,"boredomSusceptibility":0.2,"emotionalStability":0.68}'::jsonb, 'high'::"QuestComfortLevel", false, false, 240, 15, 'planned'::"QuestArchetypePace"),
  (15, 'La Lecture Profonde', 'Lire cinquante pages d''un livre exigeant dans la même journée, téléphone dans une autre pièce. À la fin, écrire une page sur ce que tu n''as pas compris plutôt que sur ce que tu as retenu.', 'Deep Reading', 'Read fifty pages of a demanding book in one day, phone in another room. At the end, write a page on what you did not understand rather than what you took away.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.8,"boredomSusceptibility":0.25,"openness":0.7}'::jsonb, 'high'::"QuestComfortLevel", false, false, 240, 7, 'instant'::"QuestArchetypePace"),
  (30, 'La Soirée Analogique', 'Une soirée complète sans aucun écran après une heure fixée (lecture papier, conversation, repos).', 'The Analog Evening', 'A full evening with no screens after a set hour (paper reading, conversation, rest).', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.68,"boredomSusceptibility":0.35,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 180, 43, 'instant'::"QuestArchetypePace"),
  (43, 'L''Heure Sans Ping', 'Une heure sans notification ni badge : mode avion partiel ou réglages, une seule activité à la fois.', 'The Hour Without Pings', 'One hour with no notifications or badges—partial airplane mode or settings, one activity only.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"boredomSusceptibility":0.35,"emotionalStability":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 60, 56, 'instant'::"QuestArchetypePace"),
  (56, 'Le Repas Hors Pièce', 'Pour un repas complet, laisser téléphone et tablette hors de la pièce où tu manges.', 'The Meal Outside the Room', 'For one full meal, leave phone and tablet outside the room where you eat.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.72,"boredomSusceptibility":0.38,"emotionalStability":0.58}'::jsonb, 'low'::"QuestComfortLevel", false, false, 45, 84, 'instant'::"QuestArchetypePace"),
  (64, 'Le Soir Sans Flux', 'Après une heure fixée, aucun écran ni flux jusqu''au coucher (lecture papier, conversation, repos).', 'The No-Feed Evening', 'After a set hour, no screens or feeds until bed (paper, conversation, rest).', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.78,"boredomSusceptibility":0.28,"emotionalStability":0.62}'::jsonb, 'high'::"QuestComfortLevel", false, false, 120, 245, 'instant'::"QuestArchetypePace"),
  (80, 'La Journée en Langue Étrangère', 'Passer une journée entière à ne consommer que du contenu dans une langue que tu ne maîtrises pas : musique, podcasts, films sans sous-titres, articles dans la langue d''origine. Écrire à la fin de la journée cinq mots que tu auras compris ou retenus.', 'The Foreign-Language Day', 'Spend an entire day consuming only content in a language you don''t master: music, podcasts, films with no subtitles, articles in the original language. At the end of the day, write down five words you caught or remembered.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"openness":0.85,"conscientiousness":0.75,"boredomSusceptibility":0.7}'::jsonb, 'high'::"QuestComfortLevel", false, false, 240, 15, 'planned'::"QuestArchetypePace"),
  (84, 'La Photo Unique', 'Ne prendre qu''UNE SEULE photo de toute la journée. Choisir consciemment le moment — attendre, rater des occasions, résister. Le reste du temps, regarder à l''œil nu, sans capture. Le soir, écrire en une phrase pourquoi ce moment-là précisément.', 'The Single Photo', 'Take only ONE photo the entire day. Choose the moment consciously — wait, miss opportunities, resist. The rest of the day, look with your eyes only, no capture. At night, write a single sentence on why that moment, precisely.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.7,"emotionalStability":0.55,"boredomSusceptibility":0.3,"openness":0.55}'::jsonb, 'low'::"QuestComfortLevel", false, false, 30, 9, 'instant'::"QuestArchetypePace"),
  (243, 'Le Week-end Hors-Ligne', 'Un week-end entier sans téléphone : l''éteindre et le ranger dans un tiroir du vendredi soir au dimanche soir. Prévenir avant qui doit l''être.', 'The Offline Weekend', 'A full weekend without your phone: switch it off and put it in a drawer from Friday evening to Sunday evening. Warn beforehand whoever needs warning.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.92,"boredomSusceptibility":0.46,"emotionalStability":0.8}'::jsonb, 'extreme'::"QuestComfortLevel", false, false, 240, 7, 'planned'::"QuestArchetypePace"),
  (244, 'La Désinstallation', 'Relever ton temps d''écran de la semaine, puis désinstaller pour sept jours l''application qui te prend le plus de temps. Relever à nouveau dans une semaine.', 'The Uninstall', 'Check your screen time for the week, then uninstall for seven days the app that takes the most of it. Check again in a week.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.84,"boredomSusceptibility":0.38,"emotionalStability":0.72}'::jsonb, 'high'::"QuestComfortLevel", false, false, 30, 84, 'instant'::"QuestArchetypePace"),
  (245, 'Le Silence Numérique', 'Ne répondre à aucun message, mail ou notification pendant une journée complète. Ne prévenir personne à l''avance.', 'The Digital Silence', 'Reply to no message, email or notification for a full day. Warn nobody in advance.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.84,"boredomSusceptibility":0.38,"emotionalStability":0.72}'::jsonb, 'high'::"QuestComfortLevel", false, false, 120, 64, 'planned'::"QuestArchetypePace"),
  (246, 'La Journée Sans Recommandation', 'Une journée sans rien consommer qu''un algorithme t''a proposé : musique, vidéos, articles, tout doit venir d''un choix que tu as fait toi-même.', 'The Day Without Recommendations', 'A day consuming nothing an algorithm suggested: music, video, articles, all of it must come from a choice you made yourself.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.74,"boredomSusceptibility":0.28,"emotionalStability":0.62}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 240, 84, 'planned'::"QuestArchetypePace"),
  (247, 'Le Téléphone Confié', 'Confier ton téléphone à quelqu''un pour une journée entière, avec l''interdiction explicite de te le rendre avant le soir, même si tu le réclames.', 'The Phone Handed Over', 'Give your phone to someone for a full day, with explicit instructions not to give it back before evening, even if you ask.', 'dopamine_detox'::"QuestPsychologicalCategory", '{"conscientiousness":0.84,"boredomSusceptibility":0.38,"emotionalStability":0.72}'::jsonb, 'high'::"QuestComfortLevel", false, true, 240, 245, 'planned'::"QuestArchetypePace"),
  (8, 'Le Pont Humain', 'Engager avec un inconnu une conversation qui dépasse trois échanges. Poser au moins deux questions sur lui avant de dire quoi que ce soit sur toi. Ne pas partir avant d''avoir appris une chose que tu n''aurais pas devinée.', 'The Human Bridge', 'Start a conversation with a stranger that goes beyond three exchanges. Ask at least two questions about them before saying anything about yourself. Do not leave before learning one thing you could not have guessed.', 'active_empathy'::"QuestPsychologicalCategory", '{"extraversion":0.82,"agreeableness":0.65,"openness":0.68,"thrillSeeking":0.5}'::jsonb, 'high'::"QuestComfortLevel", true, true, 30, 57, 'planned'::"QuestArchetypePace"),
  (14, 'Le Regret des Anciens', 'Demander à une personne bien plus âgée que toi quel est son plus grand regret. Tenir le silence après la question, ne pas la sauver, ne rien relativiser. Le soir même, noter sa réponse mot pour mot.', 'The Elders'' Regret', 'Ask someone much older than you what their greatest regret is. Hold the silence after the question, do not rescue them, soften nothing. That same evening, write their answer down word for word.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"emotionalStability":0.75,"openness":0.62}'::jsonb, 'high'::"QuestComfortLevel", false, true, 45, 8, 'planned'::"QuestArchetypePace"),
  (31, 'L''Écoute Profonde', 'Poser une question ouverte à quelqu''un et ne parler que pour reformuler ou approfondir pendant 10 minutes.', 'Deep Listening', 'Ask someone an open question and only speak to rephrase or go deeper for 10 minutes.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"conscientiousness":0.72,"boredomSusceptibility":0.25}'::jsonb, 'low'::"QuestComfortLevel", false, true, 15, 68, 'planned'::"QuestArchetypePace"),
  (44, 'Le Miroir de Phrases', 'Réformuler deux fois ce que l''autre vient de dire avant d''ajouter une seule phrase à toi.', 'The Phrase Mirror', 'Rephrase twice what the other person said before adding a single sentence of your own.', 'active_empathy'::"QuestPsychologicalCategory", '{"openness":0.75,"agreeableness":0.7,"conscientiousness":0.62}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 31, 'planned'::"QuestArchetypePace"),
  (57, 'Le Silence des Deux', 'Après avoir posé une question à quelqu''un, attendre deux minutes en silence avant de reformuler ou répondre.', 'The Silence of Two', 'After asking someone a question, wait two minutes in silence before you rephrase or answer.', 'active_empathy'::"QuestPsychologicalCategory", '{"emotionalStability":0.78,"extraversion":0.38,"conscientiousness":0.65,"boredomSusceptibility":0.2}'::jsonb, 'high'::"QuestComfortLevel", false, true, 25, 31, 'planned'::"QuestArchetypePace"),
  (65, 'Les Trois Pourquoi', 'Face à quelqu''un qui te confie un souci, poser « pourquoi » jusqu''à trois fois avec douceur avant de conseiller.', 'The Three Whys', 'When someone shares a worry, ask “why” up to three times gently before advising.', 'active_empathy'::"QuestPsychologicalCategory", '{"openness":0.72,"agreeableness":0.75,"conscientiousness":0.58,"emotionalStability":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 25, 44, 'planned'::"QuestArchetypePace"),
  (68, 'Le Vocal Bref', 'Envoyer un message vocal de 30 secondes à un proche pour dire précisément ce que tu apprécies chez lui ou elle — pas un texte, un vocal.', 'The Brief Voice Note', 'Send a 30-second voice note to someone close, saying precisely what you appreciate about them — not a text, a voice note.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.72,"extraversion":0.45,"openness":0.45}'::jsonb, 'low'::"QuestComfortLevel", false, true, 15, 31, 'instant'::"QuestArchetypePace"),
  (69, 'La Question Sincère', 'Lors d''une conversation banale aujourd''hui avec un proche ou un collègue, poser une seule question sincère (« comment tu te sens vraiment ces temps-ci ? ») et écouter la réponse sans enchaîner.', 'The Sincere Question', 'In a casual conversation today with someone close or a colleague, ask one sincere question (''how are you really doing these days?'') and listen to the answer without moving on.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"extraversion":0.5,"emotionalStability":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 44, 'instant'::"QuestArchetypePace"),
  (83, 'Le Cahier de l''Étranger', 'Aborder un inconnu (parc, café, transport long) et lui proposer de l''interviewer 15 minutes sur sa vie, sans prendre la parole sauf pour poser des questions. Noter ses mots exacts dans un cahier. À la fin, relire à voix haute une courte synthèse de ses mots — les siens, pas les tiens — avant de partir.', 'The Stranger''s Notebook', 'Approach a stranger (park, café, long-distance commute) and offer to interview them for 15 minutes about their life, speaking only to ask questions. Write down their exact words in a notebook. At the end, read aloud a short synthesis of their own words — theirs, not yours — before leaving.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"openness":0.75,"conscientiousness":0.65}'::jsonb, 'high'::"QuestComfortLevel", true, true, 45, 31, 'planned'::"QuestArchetypePace"),
  (147, 'L''Écoute Sans Conseil', 'Dans ta prochaine conversation un peu sérieuse, ne donner aucun conseil. Poser deux questions avant de répondre.', 'Listening Without Advice', 'In your next serious conversation, give no advice. Ask two questions before answering.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.68,"conscientiousness":0.55,"emotionalStability":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 31, 'instant'::"QuestArchetypePace"),
  (150, 'Le Retour Précis', 'Dire à quelqu''un aujourd''hui une qualité concrète de lui, avec un exemple précis où tu l''as vue.', 'The Precise Feedback', 'Tell someone today a concrete strength of theirs, with a precise example where you saw it.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.68,"conscientiousness":0.58,"extraversion":0.45}'::jsonb, 'low'::"QuestComfortLevel", false, true, 15, 31, 'instant'::"QuestArchetypePace"),
  (256, 'L’Heure d’un Ancien', 'Demander à une personne de plus de soixante-dix ans de te raconter une heure de sa jeunesse. Enregistrer avec son accord. Ne jamais parler de toi.', 'An Hour of an Elder', 'Ask someone over seventy to tell you an hour of their youth. Record it with their consent. Never talk about yourself.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.86,"openness":0.74,"emotionalStability":0.76}'::jsonb, 'high'::"QuestComfortLevel", false, true, 120, 14, 'planned'::"QuestArchetypePace"),
  (257, 'Le Point de Vue Adverse', 'Trouver quelqu''un dont tu ne partages pas les convictions et lui demander de te les expliquer jusqu''à ce que tu puisses les reformuler mieux que lui.', 'The Opposing View', 'Find someone whose convictions you do not share and have them explain until you can restate their position better than they can.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.86,"openness":0.74,"emotionalStability":0.76}'::jsonb, 'high'::"QuestComfortLevel", false, true, 90, 65, 'instant'::"QuestArchetypePace"),
  (258, 'La Journée Sans Je', 'Passer une journée entière de conversations sans jamais commencer une phrase par « je ». Observer le soir ce que cette contrainte a déplacé.', 'The Day Without I', 'Spend a full day of conversations never starting a sentence with "I". In the evening, note what that constraint moved.', 'active_empathy'::"QuestPsychologicalCategory", '{"agreeableness":0.94,"openness":0.82,"emotionalStability":0.84}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 240, 257, 'planned'::"QuestArchetypePace"),
  (9, 'La Lettre au Futur', 'Écrire à la main une lettre à la personne que tu veux être dans cinq ans : ce que tu espères qu''elle aura gardé, ce que tu espères qu''elle aura lâché. La ranger dans un endroit où tu la retrouveras par accident.', 'The Letter to the Future', 'Handwrite a letter to the person you want to be in five years: what you hope they kept, what you hope they let go of. Put it somewhere you will come across it by accident.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.55,"conscientiousness":0.68}'::jsonb, 'low'::"QuestComfortLevel", false, false, 45, 9, 'instant'::"QuestArchetypePace"),
  (16, 'Le Narrateur Intérieur', 'Écrire une page de ta journée à la troisième personne, comme un narrateur qui décrirait un personnage : ses gestes, ses évitements, ses petits mensonges. La relire à voix haute.', 'The Inner Narrator', 'Write a page about your day in the third person, like a narrator describing a character: their gestures, their avoidances, their small lies. Read it out loud.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.72,"conscientiousness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 60, 9, 'instant'::"QuestArchetypePace"),
  (20, 'La Vie Hardie', 'Nommer par écrit les trois moments où tu sais que tu t''es dégonflé. Puis écrire trois pages de l''histoire de ta vie telle qu''elle aurait été si tu avais tenu bon à ces trois moments-là.', 'The Bold Life', 'Write down the three moments you know you backed down. Then write three pages of your life story as it would have gone if you had held your ground at those three moments.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.82,"emotionalStability":0.68,"thrillSeeking":0.5}'::jsonb, 'high'::"QuestComfortLevel", false, false, 120, 9, 'instant'::"QuestArchetypePace"),
  (21, 'La Bande-Son du Futur', 'Composer une playlist d''une heure pour la version de toi que tu es en train de devenir, pas celle que tu as été. L''écouter en entier une fois, en marchant, sans rien faire d''autre.', 'The Future Soundtrack', 'Build a one-hour playlist for the version of you that you are becoming, not the one you have been. Listen to all of it once, walking, doing nothing else.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.75,"conscientiousness":0.5,"boredomSusceptibility":0.35}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 60, 9, 'instant'::"QuestArchetypePace"),
  (32, 'La Lettre du Non', 'Écrire une page adressée à une version de toi qui dit toujours non par peur : ce que tu lui refuserais encore.', 'The Letter of No', 'Write a page to a version of you who always says no out of fear: what you''d still refuse.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.65,"emotionalStability":0.7,"conscientiousness":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, false, 45, 9, 'instant'::"QuestArchetypePace"),
  (45, 'Les Trois Futurs', 'Écrire en trois paragraphes : ton futur dans un mois, dans un an, dans dix ans — sans juger le texte.', 'The Three Futures', 'Write three paragraphs: your future in one month, one year, ten years—without judging the draft.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.65,"conscientiousness":0.62}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 60, 9, 'instant'::"QuestArchetypePace"),
  (58, 'La Frise des Cinq Ans', 'Sur une page, dessiner une frise des cinq dernières années avec au moins cinq jalons datés.', 'The Five-Year Timeline', 'On one page, draw a timeline of the last five years with at least five dated milestones.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.55,"conscientiousness":0.7}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 50, 9, 'instant'::"QuestArchetypePace"),
  (78, 'La Lettre aux Dix Ans', 'Écrire à toi-même dans dix ans exactement : qui tu veux être, ce que tu espères avoir fait, ce que tu as peur de devenir. Trois pages minimum, manuscrit. Puis programmer son envoi via un service de lettre future (futureme.org) pour l''ouvrir à la date exacte.', 'The Ten-Year Letter', 'Write to yourself ten years from now exactly: who you want to be, what you hope to have done, what you fear becoming. Three pages minimum, handwritten. Then schedule its delivery via a future-letter service (futureme.org) to open on the exact date.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.72,"conscientiousness":0.7,"emotionalStability":0.6,"boredomSusceptibility":0.25}'::jsonb, 'extreme'::"QuestComfortLevel", false, false, 180, 9, 'planned'::"QuestArchetypePace"),
  (85, 'La Lettre aux Six Mois', 'Écrire à la main (pas au clavier) une lettre à toi-même datée de six mois dans le futur. La sceller dans une enveloppe avec la date d''ouverture écrite dessus. La déposer chez un ami de confiance ou dans un lieu caché (boîte verrouillée, livre rangé) que tu t''engages à revisiter à cette date précise.', 'The Six-Month Letter', 'Handwrite (not type) a letter to yourself dated six months in the future. Seal it in an envelope with the opening date written on it. Drop it at a trusted friend''s or in a hidden place (locked box, shelved book) you commit to revisit on that exact date.', 'temporal_projection'::"QuestPsychologicalCategory", '{"conscientiousness":0.65,"openness":0.62,"emotionalStability":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 40, 9, 'instant'::"QuestArchetypePace"),
  (248, 'L’Épitaphe', 'Écrire honnêtement le texte qu''on lirait à ton enterrement si tu mourais demain. Puis écrire celui que tu voudrais qu''on lise. Comparer les deux et souligner l''écart.', 'The Eulogy', 'Honestly write the text that would be read at your funeral if you died tomorrow. Then write the one you would want read. Compare the two and underline the gap.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.92,"emotionalStability":0.84,"conscientiousness":0.73}'::jsonb, 'extreme'::"QuestComfortLevel", false, false, 90, 250, 'planned'::"QuestArchetypePace"),
  (249, 'La Liste des Renoncements', 'Lister dix choses que tu as décidé, sans jamais le dire, que tu ne feras jamais. En choisir une et la rayer de la liste pour cette année.', 'The List of Givens-Up', 'List ten things you have quietly decided you will never do. Pick one and cross it off the list for this year.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.84,"emotionalStability":0.76,"conscientiousness":0.65}'::jsonb, 'high'::"QuestComfortLevel", false, false, 60, 32, 'instant'::"QuestArchetypePace"),
  (250, 'Le Compte à Rebours', 'Calculer combien de fois il te reste statistiquement à voir tes parents, à voir un été, à lire un livre. Écrire ce que ces trois chiffres changent à ta semaine.', 'The Countdown', 'Work out how many times you have left, statistically, to see your parents, to see a summer, to read a book. Write what those three numbers change about your week.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.84,"emotionalStability":0.76,"conscientiousness":0.65}'::jsonb, 'high'::"QuestComfortLevel", false, false, 90, 249, 'planned'::"QuestArchetypePace"),
  (251, 'La Lettre au Passé', 'Écrire à toi-même il y a cinq ans : ce que tu lui dirais, et surtout ce que tu lui cacherais volontairement.', 'The Letter to the Past', 'Write to yourself five years ago: what you would tell them, and above all what you would deliberately keep from them.', 'temporal_projection'::"QuestPsychologicalCategory", '{"openness":0.74,"emotionalStability":0.66,"conscientiousness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 60, 9, 'instant'::"QuestArchetypePace"),
  (10, 'L''Immersion Totale', 'Aller à un événement où tu ne connais personne et où personne ne t''attend. Interdiction de repartir avant d''avoir eu une vraie conversation avec deux personnes différentes.', 'Total Immersion', 'Go to an event where you know nobody and nobody expects you. You may not leave before having a real conversation with two different people.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.85,"thrillSeeking":0.75,"emotionalStability":0.78}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 180, 33, 'planned'::"QuestArchetypePace"),
  (33, 'L''Autre Monde', 'Passer au moins une heure dans un lieu où tu te sens minoritaire (langue, âge, scène) et rester jusqu''à être un peu à l''aise.', 'The Other World', 'Spend at least an hour somewhere you feel in the minority (language, age, scene) until you settle a bit.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.65,"openness":0.78,"emotionalStability":0.8,"thrillSeeking":0.6}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 120, 260, 'planned'::"QuestArchetypePace"),
  (46, 'La Première Main Levée', 'Dans un groupe (réunion, cours, apéro), prendre la parole une première fois même si la voix tremble.', 'The First Hand Raised', 'In a group (meeting, class, drinks), speak up once even if your voice shakes.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.78,"emotionalStability":0.72,"thrillSeeking":0.55}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 90, 59, 'planned'::"QuestArchetypePace"),
  (59, 'Le Stand Inconnu', 'Traverser seul l''entrée d''un salon, d''une foire ou d''un forum et poser une question précise à un exposant.', 'The Unknown Booth', 'Enter a fair or expo alone and ask one specific question to an exhibitor.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.72,"openness":0.65,"emotionalStability":0.7,"thrillSeeking":0.55}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 75, 259, 'planned'::"QuestArchetypePace"),
  (72, 'Le Désaccord Tenu', 'Dans une conversation aujourd''hui (réunion, repas, discussion en ligne), exprimer un désaccord franc sur un point précis sans l''adoucir et tenir la position 30 secondes face à la réaction.', 'The Held Disagreement', 'In a conversation today (meeting, meal, online thread), express frank disagreement on a specific point without softening it and hold the position for 30 seconds against the reaction.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.6,"emotionalStability":0.6,"thrillSeeking":0.55,"agreeableness":0.35}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 30, 164, 'instant'::"QuestArchetypePace"),
  (82, 'Le Pseudonyme d''un Soir', 'Lors d''une soirée, un meetup ou un événement public où tu ne connais personne, te présenter sous un autre prénom et un autre métier pendant deux heures. Observer comment les autres te perçoivent — et comment toi-même tu te perçois autrement. Révéler avant de partir si tu veux (ou pas).', 'The Alias for an Evening', 'At a party, meetup or public event where you know no one, introduce yourself under a different first name and a different job for two hours. Watch how others perceive you — and how you perceive yourself. Reveal before leaving if you want (or not).', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.72,"thrillSeeking":0.68,"openness":0.65,"agreeableness":0.45}'::jsonb, 'high'::"QuestComfortLevel", true, true, 120, 72, 'planned'::"QuestArchetypePace"),
  (163, 'Le Regard Tenu', 'Avec une personne de ton choix aujourd''hui, tenir son regard 10 secondes pleines sans rire ni détourner.', 'The Held Gaze', 'With a person of your choice today, hold eye contact a full 10 seconds without laughing or looking away.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"emotionalStability":0.6,"extraversion":0.5,"thrillSeeking":0.45}'::jsonb, 'high'::"QuestComfortLevel", false, true, 15, 9, 'instant'::"QuestArchetypePace"),
  (164, 'L''Opinion Donnée', 'Dans une conversation aujourd''hui, donner une opinion tranchée sur un petit sujet sans dire « je sais pas trop ».', 'The Opinion Given', 'In a conversation today, give a clear opinion on a small topic without saying ''I don''t really know''.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.55,"emotionalStability":0.58,"thrillSeeking":0.48,"agreeableness":0.4}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 9, 'instant'::"QuestArchetypePace"),
  (165, 'La Question Gênante', 'Poser à quelqu''un une question un peu gênante mais sincère (« tu rêves de quoi en ce moment ? », « qu''est-ce qui te fait peur ? »).', 'The Awkward Question', 'Ask someone a slightly awkward but sincere question (''what are you dreaming about?'', ''what scares you?'').', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.5,"openness":0.62,"thrillSeeking":0.48}'::jsonb, 'high'::"QuestComfortLevel", false, true, 20, 166, 'instant'::"QuestArchetypePace"),
  (166, 'Le Non Clair', 'Dire non à une sollicitation aujourd''hui sans t''excuser, sans justifier longuement. Juste « non, pas cette fois ».', 'The Clear No', 'Say no to a request today without apologizing, without long justifications. Just ''no, not this time''.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"emotionalStability":0.6,"conscientiousness":0.55,"agreeableness":0.4}'::jsonb, 'high'::"QuestComfortLevel", false, true, 20, 165, 'instant'::"QuestArchetypePace"),
  (167, 'Le Premier Pas', 'Engager la conversation avec un·e inconnu·e aujourd''hui par une question ouverte (pas « il fait beau », plutôt « d''où venez-vous ? »).', 'The First Step', 'Start a conversation with a stranger today with an open question (not ''nice weather'' but ''where are you from?'').', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.58,"openness":0.58,"thrillSeeking":0.5}'::jsonb, 'high'::"QuestComfortLevel", false, true, 25, 165, 'instant'::"QuestArchetypePace"),
  (259, 'La Collection de Refus', 'Demander volontairement trois choses déraisonnables aujourd''hui pour collectionner trois refus. Le but est le non, pas le oui.', 'The Collection of Nos', 'Deliberately ask for three unreasonable things today in order to collect three refusals. The goal is the no, not the yes.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.8,"thrillSeeking":0.75,"emotionalStability":0.82}'::jsonb, 'high'::"QuestComfortLevel", true, true, 60, 72, 'instant'::"QuestArchetypePace"),
  (260, 'Le Micro Pris', 'Prendre la parole devant un public qui ne te connaît pas : scène ouverte, karaoké, ou une question posée à voix haute en fin de conférence.', 'The Mic Taken', 'Speak in front of an audience that does not know you: open mic, karaoke, or a question asked out loud at the end of a talk.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.88,"thrillSeeking":0.83,"emotionalStability":0.9}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 120, 46, 'planned'::"QuestArchetypePace"),
  (261, 'La Critique Demandée', 'Demander à quelqu''un dont l''avis compte de critiquer franchement ton travail, et l''écouter sans te défendre une seule fois.', 'The Criticism Requested', 'Ask someone whose opinion matters to criticize your work honestly, and listen without defending yourself a single time.', 'hostile_immersion'::"QuestPsychologicalCategory", '{"extraversion":0.8,"thrillSeeking":0.75,"emotionalStability":0.82}'::jsonb, 'high'::"QuestComfortLevel", false, true, 60, 259, 'planned'::"QuestArchetypePace"),
  (11, 'Le Rayon de Soleil', 'Complimenter sincèrement cinq inconnus dans la même journée, sur quelque chose qu''ils ont choisi et non sur ce qu''ils sont. Ne rien attendre en retour, ne pas rester pour la réaction.', 'The Ray of Sunshine', 'Give five strangers a genuine compliment in one day, about something they chose rather than something they are. Expect nothing back, do not stay for the reaction.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"extraversion":0.82,"agreeableness":0.7,"thrillSeeking":0.4}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 60, 200, 'planned'::"QuestArchetypePace"),
  (34, 'Le Mot Égaré', 'Laisser un mot manuscrit d''encouragement dans un lieu public (sans signature narcissique).', 'The Misplaced Word', 'Leave a handwritten note of encouragement in a public place (no narcissistic signature).', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"openness":0.72,"agreeableness":0.72,"extraversion":0.35,"conscientiousness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", true, false, 45, 204, 'instant'::"QuestArchetypePace"),
  (47, 'Le Pourboire d''Aujourd''hui', 'Offrir un pourboire ou un geste de reconnaissance inhabituel à quelqu''un qui t''a servi (café, soin, livraison).', 'Today''s Tip', 'Give an unusually generous tip or thank-you to someone who served you (café, care, delivery).', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"conscientiousness":0.68,"extraversion":0.5}'::jsonb, 'low'::"QuestComfortLevel", true, true, 25, 60, 'planned'::"QuestArchetypePace"),
  (60, 'Le Café Suivant', 'Si le lieu le permet, régler discrètement le café ou le thé de la personne derrière toi à la file.', 'The Next Coffee', 'If the place allows, quietly pay for the coffee or tea of the person behind you in line.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.72,"thrillSeeking":0.45,"openness":0.6}'::jsonb, 'low'::"QuestComfortLevel", true, true, 20, 9, 'planned'::"QuestArchetypePace"),
  (198, 'La Demi-Journée des Inconnus', 'Consacrer une demi-journée à rendre trois services à des inconnus, sans jamais expliquer pourquoi tu le fais. Partir avant les remerciements à chaque fois.', 'The Half-Day for Strangers', 'Spend half a day doing three favors for strangers, never explaining why. Leave before the thanks each time.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.86,"extraversion":0.72,"openness":0.65}'::jsonb, 'high'::"QuestComfortLevel", true, true, 240, 11, 'planned'::"QuestArchetypePace"),
  (199, 'Le Repas Offert', 'Acheter un vrai repas chaud et l''offrir en main propre à quelqu''un qui dort dehors. Puis s''asseoir et parler cinq minutes, comme à n''importe qui.', 'The Meal Handed Over', 'Buy a real hot meal and hand it directly to someone sleeping rough. Then sit down and talk for five minutes, the way you would with anyone.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.86,"extraversion":0.72,"openness":0.65}'::jsonb, 'high'::"QuestComfortLevel", true, true, 90, 47, 'planned'::"QuestArchetypePace"),
  (200, 'Le Coup de Main Non Sollicité', 'Repérer dans l''espace public quelqu''un en difficulté visible et proposer ton aide avant qu''on te la demande. Insister une fois si on refuse par politesse.', 'The Unasked Hand', 'Spot someone visibly struggling in public and offer help before being asked. Insist once if they refuse out of politeness.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.76,"extraversion":0.62,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 60, 11, 'instant'::"QuestArchetypePace"),
  (201, 'L’Anonyme Généreux', 'Faire un geste matériel réel pour quelqu''un de ton entourage en t''assurant qu''il ne saura jamais que ça vient de toi. Tenir le secret même s''il cherche.', 'The Anonymous Giver', 'Do something materially real for someone close to you, making sure they never learn it came from you. Keep the secret even if they dig.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.86,"extraversion":0.72,"openness":0.65}'::jsonb, 'high'::"QuestComfortLevel", false, false, 60, 34, 'planned'::"QuestArchetypePace"),
  (202, 'Les Trois Heures Données', 'Contacter une association près de chez toi et donner trois heures de ton temps cette semaine. Pas un don d''argent : ta présence, un après-midi.', 'Three Hours Given', 'Contact a local charity and give three hours of your time this week. Not money: your presence, one afternoon.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.94,"extraversion":0.8,"openness":0.73}'::jsonb, 'extreme'::"QuestComfortLevel", true, true, 180, 199, 'planned'::"QuestArchetypePace"),
  (203, 'La Compétence Prêtée', 'Offrir gratuitement à quelqu''un une heure de ce que tu sais faire le mieux. Le proposer explicitement, ne pas attendre qu''on devine.', 'The Skill Lent', 'Give someone one free hour of the thing you are best at. Offer it explicitly, do not wait to be asked.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.76,"extraversion":0.62,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 90, 11, 'planned'::"QuestArchetypePace"),
  (204, 'Le Voisin Nommé', 'Frapper chez un voisin dont tu ignores le prénom. Te présenter. Repartir avec son prénom et une chose vraie sur lui.', 'The Neighbor Named', 'Knock on the door of a neighbor whose first name you do not know. Introduce yourself. Leave with their name and one true thing about them.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.76,"extraversion":0.62,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 45, 34, 'instant'::"QuestArchetypePace"),
  (205, 'La Chaîne Lancée', 'Faire un geste gratuit pour quelqu''un et lui demander une seule chose en retour : le refaire pour une autre personne cette semaine.', 'The Chain Started', 'Do something for someone at no cost and ask one thing in return: that they do the same for someone else this week.', 'spontaneous_altruism'::"QuestPsychologicalCategory", '{"agreeableness":0.76,"extraversion":0.62,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 60, 200, 'instant'::"QuestArchetypePace"),
  (12, 'La Reconnexion', 'Appeler — pas écrire — un ami que tu as laissé filer. Dire d''emblée que ça fait trop longtemps et que c''est aussi de ta faute. Proposer une date précise avant de raccrocher.', 'The Reconnection', 'Call, do not text, a friend you let drift. Say straight away that it has been too long and that it is partly on you. Propose a specific date before hanging up.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.72,"emotionalStability":0.65}'::jsonb, 'high'::"QuestComfortLevel", false, true, 30, 35, 'planned'::"QuestArchetypePace"),
  (22, 'La Journée Sans Mensonge', 'Pendant une journée entière, ne dire que la vérité, y compris dans les petits arrangements sociaux : « ça va », « c''était très bien », « je n''ai pas eu le temps ». Le soir, écrire ce que ça a coûté et ce que ça a soulagé.', 'The Day Without Lies', 'For a full day, tell only the truth, including in the small social arrangements: "I''m fine", "it was great", "I didn''t have time". That evening, write what it cost and what it relieved.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.6,"emotionalStability":0.82,"conscientiousness":0.6}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 240, 12, 'planned'::"QuestArchetypePace"),
  (35, 'Le Remerciement Tardif', 'Dire à un proche une chose précise que tu apprécies chez lui depuis longtemps sans l''avoir dit.', 'The Late Thank-You', 'Tell someone close something specific you appreciate about them that you''ve long left unsaid.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"emotionalStability":0.62}'::jsonb, 'high'::"QuestComfortLevel", false, true, 30, 12, 'planned'::"QuestArchetypePace"),
  (48, 'Le Vocal de Vérité', 'Envoyer un message vocal d''environ une minute à quelqu''un que tu évites, sans mentir sur l''essentiel.', 'The Truth Voice Note', 'Send a ~1-minute voice message to someone you''ve been avoiding, honest on what matters.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.62,"emotionalStability":0.72}'::jsonb, 'high'::"QuestComfortLevel", false, true, 15, 181, 'planned'::"QuestArchetypePace"),
  (61, 'La Phrase en Je', 'Écrire ou dire une phrase qui commence par « j''ai besoin » ou « je ressens », sans accuser l''autre.', 'The I-Statement', 'Write or say a sentence starting with “I need” or “I feel,” without blaming the other person.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.7,"emotionalStability":0.72}'::jsonb, 'high'::"QuestComfortLevel", false, true, 20, 176, 'planned'::"QuestArchetypePace"),
  (70, 'L''Aveu Léger', 'Partager à une personne de confiance une petite vulnérabilité que tu n''as jamais dite à voix haute (un doute, une peur modeste, un regret). Rien de dramatique — juste du vrai.', 'The Light Confession', 'Share with someone you trust a small vulnerability you''ve never said out loud (a doubt, a modest fear, a regret). Nothing dramatic — just honest.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.68,"openness":0.6,"emotionalStability":0.5}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 30, 71, 'instant'::"QuestArchetypePace"),
  (71, 'Le Remerciement Concret', 'Remercier explicitement une personne précise pour un geste passé en nommant ce que ça t''a fait — pas un « merci » générique, mais « quand tu as fait X, voilà ce que ça a changé pour moi ».', 'The Concrete Thanks', 'Thank a specific person for a past action by naming what it did for you — not a generic ''thanks'', but ''when you did X, here''s what it changed for me''.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.75,"extraversion":0.5,"openness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 25, 179, 'instant'::"QuestArchetypePace"),
  (81, 'Le Miroir des Proches', 'Contacter trois personnes proches (amis, famille, partenaire) et leur demander individuellement : « quelle est ma pire habitude selon toi ? ». Écouter sans commenter ni te défendre. Noter textuellement leurs mots. Ne répondre à aucune avant le lendemain.', 'The Mirror of Loved Ones', 'Reach out to three people close to you (friends, family, partner) and ask each separately: ''what''s my worst habit in your eyes?''. Listen without commenting or defending. Write down their exact words. Don''t reply to any of them before the next day.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"emotionalStability":0.72,"openness":0.7,"agreeableness":0.65}'::jsonb, 'high'::"QuestComfortLevel", false, true, 60, 70, 'planned'::"QuestArchetypePace"),
  (176, 'La Phrase Retenue', 'Dire à voix haute à un proche aujourd''hui une phrase que tu penses sans jamais la dire (« tu comptes pour moi »).', 'The Held-Back Sentence', 'Say out loud to someone close a sentence you think but never say (''you matter to me'').', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.65,"emotionalStability":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, true, 20, 61, 'instant'::"QuestArchetypePace"),
  (178, 'Le Besoin Nommé', 'Dire à quelqu''un aujourd''hui une chose dont tu as besoin, clairement, sans détour (« j''aurais besoin que tu... »).', 'The Named Need', 'Tell someone today one thing you need, clearly, directly (''I''d need you to...'').', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"emotionalStability":0.58,"agreeableness":0.55,"conscientiousness":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, true, 20, 61, 'instant'::"QuestArchetypePace"),
  (179, 'L''Émotion Dite', 'Dans une conversation aujourd''hui, nommer ton émotion réelle (« je suis un peu triste, un peu fatigué·e ») au lieu de « ça va ».', 'The Named Emotion', 'In a conversation today, name your real emotion (''I''m a bit sad, a bit tired'') instead of ''I''m fine''.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"emotionalStability":0.58,"agreeableness":0.6}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 20, 181, 'instant'::"QuestArchetypePace"),
  (181, 'Le Compliment Reçu', 'La prochaine fois qu''on te complimente aujourd''hui, dire simplement « merci, ça me touche », sans minimiser ni retourner.', 'The Compliment Received', 'Next time you get a compliment today, just say ''thanks, that means a lot'', no minimizing, no deflecting.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"emotionalStability":0.6,"agreeableness":0.6}'::jsonb, 'low'::"QuestComfortLevel", false, true, 15, 9, 'instant'::"QuestArchetypePace"),
  (182, 'L''Excuse Tenue', 'Si tu as été maladroit·e récemment avec quelqu''un, lui envoyer un « désolé·e, j''ai été X » sans justification.', 'The Plain Apology', 'If you were clumsy with someone recently, send them ''sorry, I was X'' with no justification.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"emotionalStability":0.6,"agreeableness":0.65,"conscientiousness":0.58}'::jsonb, 'high'::"QuestComfortLevel", false, true, 25, 61, 'instant'::"QuestArchetypePace"),
  (262, 'La Conversation Reportée', 'Avoir enfin la conversation que tu repousses depuis des mois, avec la personne concernée, en face à face. Pas par message, pas au téléphone.', 'The Postponed Conversation', 'Finally have the conversation you have been putting off for months, with the person concerned, face to face. Not by message, not by phone.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.88,"emotionalStability":0.8,"openness":0.76}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 120, 12, 'planned'::"QuestArchetypePace"),
  (263, 'Le Premier Pas du Pardon', 'Reprendre contact avec une personne avec qui tu es fâché, sans exiger d''excuses et sans en donner d''emblée. Juste rouvrir la porte.', 'The First Step Back', 'Get back in touch with someone you fell out with, demanding no apology and offering none upfront. Just reopen the door.', 'relational_vulnerability'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"emotionalStability":0.72,"openness":0.68}'::jsonb, 'high'::"QuestComfortLevel", false, true, 90, 12, 'planned'::"QuestArchetypePace"),
  (13, 'Le Festin Altruiste', 'Cuisiner un vrai repas pour quelqu''un qui ne s''y attend pas, construit autour de ce que cette personne aime et non de ce que toi tu aimes. Le servir, débarrasser, et refuser qu''on t''aide.', 'The Altruistic Feast', 'Cook a real meal for someone who is not expecting it, built around what they like rather than what you like. Serve it, clear it away, and refuse any help.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"conscientiousness":0.62}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 120, 210, 'planned'::"QuestArchetypePace"),
  (36, 'Le Cadeau Sans Occasion', 'Offrir un petit cadeau ou un repas à un voisin ou un collègue sans occasion particulière.', 'The Gift Without Occasion', 'Give a small gift or a meal to a neighbor or colleague for no special reason.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.82,"conscientiousness":0.55}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 90, 206, 'planned'::"QuestArchetypePace"),
  (49, 'Le Plat Dédicacé', 'Préparer un plat ou un goûter pour une personne précise et le lui remettre en main propre avec une phrase simple.', 'The Dedicated Dish', 'Cook a dish or snack for a specific person and hand it to them with one simple sentence.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.78,"conscientiousness":0.68}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 75, 62, 'planned'::"QuestArchetypePace"),
  (62, 'La Course Sans Redemande', 'Accomplir une course ou une démarche administrative pour quelqu''un de proche sans qu''on te la redemande.', 'The Errand Unasked', 'Run one errand or admin task for someone close without them asking again.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.75,"conscientiousness":0.75}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 60, 213, 'planned'::"QuestArchetypePace"),
  (206, 'La Corvée Invisible', 'Prendre en charge entièrement, pendant une semaine, une tâche que fait toujours quelqu''un d''autre chez toi. Sans l''annoncer au début, sans le mentionner à la fin.', 'The Invisible Chore', 'Take over completely, for one week, a task someone else always does in your home. Do not announce it at the start, do not mention it at the end.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"conscientiousness":0.6,"extraversion":0.45}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 90, 36, 'planned'::"QuestArchetypePace"),
  (207, 'Le Déménagement Proposé', 'Proposer ton aide physique à quelqu''un pour une corvée lourde : déménagement, débarras, travaux. Y aller. Ne pas partir avant que ce soit fini.', 'The Offered Move', 'Offer someone your physical help with heavy work: a move, a clear-out, repairs. Show up. Do not leave before it is finished.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.9,"conscientiousness":0.7,"extraversion":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, true, 240, 206, 'planned'::"QuestArchetypePace"),
  (208, 'La Journée à Disposition', 'Dire à un proche : « aujourd''hui je suis à ta disposition, de quoi tu as besoin ? » Puis tenir toute la journée, quoi qu''il demande, sans négocier.', 'The Day at Their Disposal', 'Tell someone close: "today I am at your disposal, what do you need?" Then hold it all day, whatever they ask, without negotiating.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.95,"conscientiousness":0.78,"extraversion":0.63}'::jsonb, 'extreme'::"QuestComfortLevel", false, true, 240, 207, 'planned'::"QuestArchetypePace"),
  (209, 'Le Silence sur le Geste', 'Rendre un service qui compte vraiment à quelqu''un, puis refuser explicitement tout remerciement et toute contrepartie. Couper court à chaque tentative.', 'No Thanks Taken', 'Do something that genuinely matters for someone, then explicitly refuse all thanks and anything in return. Cut off every attempt.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.9,"conscientiousness":0.7,"extraversion":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, true, 60, 62, 'instant'::"QuestArchetypePace"),
  (210, 'La Réparation Offerte', 'Réparer ou remettre en état un objet cassé qui appartient à quelqu''un d''autre, et le lui rendre sans commentaire ni explication.', 'The Repair Given', 'Fix or restore something broken that belongs to someone else, and hand it back with no comment and no explanation.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"conscientiousness":0.6,"extraversion":0.45}'::jsonb, 'moderate'::"QuestComfortLevel", false, false, 120, 206, 'planned'::"QuestArchetypePace"),
  (211, 'Le Trajet Fait', 'Accompagner physiquement quelqu''un à un rendez-vous qu''il redoute : médecin, administration, entretien. Attendre dehors s''il le faut.', 'The Trip Made', 'Physically go with someone to an appointment they dread: doctor, paperwork, interview. Wait outside if that is what helps.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"conscientiousness":0.6,"extraversion":0.45}'::jsonb, 'moderate'::"QuestComfortLevel", true, true, 90, 62, 'planned'::"QuestArchetypePace"),
  (212, 'L’Heure d’Écoute', 'Dire à une personne qui traverse quelque chose de difficile : « je suis là une heure, raconte. » Ne donner aucun conseil, ne rien ramener à toi.', 'The Listening Hour', 'Tell someone going through something hard: "I am here for an hour, talk." Give no advice, bring nothing back to yourself.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.9,"conscientiousness":0.7,"extraversion":0.55}'::jsonb, 'high'::"QuestComfortLevel", false, true, 90, 209, 'planned'::"QuestArchetypePace"),
  (213, 'Le Legs d’un Objet', 'Donner à quelqu''un un objet auquel tu tiens vraiment, en lui expliquant précisément pourquoi tu y tenais.', 'The Object Passed On', 'Give someone an object you genuinely care about, telling them exactly why it mattered to you.', 'unconditional_service'::"QuestPsychologicalCategory", '{"agreeableness":0.8,"conscientiousness":0.6,"extraversion":0.45}'::jsonb, 'moderate'::"QuestComfortLevel", false, true, 45, 9, 'instant'::"QuestArchetypePace")
